window.CARD_CODE="/*\r\n * Copyright 2023 Adobe. All rights reserved.\r\n * This file is licensed to you under the Apache License, Version 2.0 (the \"License\");\r\n * you may not use this file except in compliance with the License. You may obtain a copy\r\n * of the License at http://www.apache.org/licenses/LICENSE-2.0\r\n *\r\n * Unless required by applicable law or agreed to in writing, software distributed under\r\n * the License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR REPRESENTATIONS\r\n * OF ANY KIND, either express or implied. See the License for the specific language\r\n * governing permissions and limitations under the License.\r\n */\r\n\r\nimport {filterDOMProps} from 'react-aria/filterDOMProps';\r\n\r\nimport {getEventTarget} from 'react-aria/private/utils/shadowdom/DOMFunctions';\r\nimport {GlobalDOMAttributes} from '@react-types/shared';\r\nimport {Input} from './Input';\r\nimport {PressResponder} from 'react-aria/private/interactions/PressResponder';\r\nimport React, {ForwardedRef, forwardRef, ReactNode} from 'react';\r\nimport {useObjectRef} from 'react-aria/useObjectRef';\r\n\r\nexport interface FileTriggerProps extends GlobalDOMAttributes<HTMLInputElement> {\r\n  /**\r\n   * Specifies what mime type of files are allowed.\r\n   */\r\n  acceptedFileTypes?: ReadonlyArray<string>;\r\n  /**\r\n   * Whether multiple files can be selected.\r\n   */\r\n  allowsMultiple?: boolean;\r\n  /**\r\n   * Specifies the use of a media capture mechanism to capture the media on the spot.\r\n   */\r\n  defaultCamera?: 'user' | 'environment';\r\n  /**\r\n   * Handler when a user selects a file.\r\n   */\r\n  onSelect?: (files: FileList | null) => void;\r\n  /**\r\n   * The children of the component.\r\n   */\r\n  children?: ReactNode;\r\n  /**\r\n   * Enables the selection of directories instead of individual files.\r\n   */\r\n  acceptDirectory?: boolean;\r\n}\r\n\r\n/**\r\n * A FileTrigger allows a user to access the file system with any pressable React Aria or React\r\n * Spectrum component, or custom components built with usePress.\r\n */\r\nexport const FileTrigger = forwardRef(function FileTrigger(\r\n  props: FileTriggerProps,\r\n  ref: ForwardedRef<HTMLInputElement>\r\n) {\r\n  let {\r\n    onSelect,\r\n    acceptedFileTypes,\r\n    allowsMultiple,\r\n    defaultCamera,\r\n    children,\r\n    acceptDirectory,\r\n    ...rest\r\n  } = props;\r\n  let inputRef = useObjectRef(ref);\r\n  let domProps = filterDOMProps(rest, {global: true});\r\n\r\n  return (\r\n    <>\r\n      <PressResponder\r\n        onPress={() => {\r\n          if (inputRef.current?.value) {\r\n            inputRef.current.value = '';\r\n          }\r\n          inputRef.current?.click();\r\n        }}>\r\n        {children}\r\n      </PressResponder>\r\n      <Input\r\n        {...domProps}\r\n        className=\"\"\r\n        type=\"file\"\r\n        ref={inputRef}\r\n        onClick={e => e.stopPropagation()}\r\n        style={{display: 'none'}}\r\n        accept={acceptedFileTypes?.toString()}\r\n        onChange={e => onSelect?.(getEventTarget(e).files)}\r\n        capture={defaultCamera}\r\n        multiple={allowsMultiple}\r\n        // @ts-expect-error\r\n        webkitdirectory={acceptDirectory ? '' : undefined}\r\n      />\r\n    </>\r\n  );\r\n});\r\n";
